&lt;table class=&quot;Bestiaire&quot;&gt;&lt;tr&gt;&lt;td&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Seigneur des haches&lt;div style=&quot;float:right;&quot;&gt;FP 16&lt;/div&gt;&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : &lt;a class=&quot;pagelink&quot; href=&quot;Manuel-Des-Pnj-(Contenu).html&quot; title=&quot;Manuel des PNJ (Contenu)&quot;&gt;Manuel des PNJ p. 124&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;PX&lt;/b&gt; 76 800
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Nain.html&quot; title=&quot;Les nains&quot;&gt;Nain&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html&quot; title=&quot;Le paladin&quot;&gt;paladin&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Torag-(Technique).html&quot; title=&quot;Torag&quot;&gt;Torag&lt;/a&gt; 17
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Type-Humano&#239;de.html&quot; title=&quot;Humano&#239;de&quot;&gt;Humano&#239;de&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Nain.html&quot; title=&quot;Nain (sous-type)&quot;&gt;nain&lt;/a&gt;) de taille M, LB
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Init&lt;/b&gt; +3 ; &lt;b&gt;Sens&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +12
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Aura&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#AURADECOURAGE&quot; title=&quot;Le paladin&quot;&gt;courage&lt;/a&gt; (3 m), &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#AURADEDROITURE&quot; title=&quot;Le paladin&quot;&gt;droiture&lt;/a&gt; (3 m), &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#AURADEFERMETE&quot; title=&quot;Le paladin&quot;&gt;fermet&#233;&lt;/a&gt; (3 m), &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#AURADEFOI&quot; title=&quot;Le paladin&quot;&gt;foi&lt;/a&gt; (3 m), &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#AURADEJUSTICE&quot; title=&quot;Le paladin&quot;&gt;justice&lt;/a&gt; (3 m)
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;D&#233;fense&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;CA&lt;/b&gt; 26, contact 11, pris au d&#233;pourvu 26 (armure +10, bouclier +4, Dex -1, naturelle +1, parade +2)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;pv&lt;/b&gt; 183 (17d10+85)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;R&#233;f&lt;/b&gt; +7, &lt;b&gt;Vig&lt;/b&gt; +16, &lt;b&gt;Vol&lt;/b&gt; +15 ; +2 contre le poison, les sorts et les pouvoirs magiques
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Capacit&#233;s d&#233;fensives&lt;/b&gt; entra&#238;nement d&#233;fensif (bonus d&#39;esquive de +4 &#224; la CA contre les g&#233;ants) ; &lt;b&gt;Immunit&#233;s&lt;/b&gt; charme, coercition, maladie, peur, poison ; &lt;b&gt;RD&lt;/b&gt; 5/Mal
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Attaque&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;VD&lt;/b&gt; 6 m
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Corps &#224; corps&lt;/b&gt; &lt;i&gt;hache d&#39;armes naine de foudre +3&lt;/i&gt;, +27/+22/+17/+12 (1d10+9/19–20/&#215;3 plus 1d6 &#233;lectricit&#233;)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Distance&lt;/b&gt; &lt;i&gt;hache de lancer +1&lt;/i&gt;, +17/+12/+7/+2 (1d6+7)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; +1 aux jets d&#39;attaque contre les humano&#239;des gobelino&#239;des et orques, &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#CANALISATIONDENERGIEPOSITIVE&quot; title=&quot;Le paladin&quot;&gt;canalisation d&#39;&#233;nergie positive&lt;/a&gt; (DD 20, 9d6), &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#CHATIMENTDUMAL&quot; title=&quot;Le paladin&quot;&gt;ch&#226;timent du mal&lt;/a&gt; 6/jour (+2 &#224; l&#39;attaque et &#224; la CA, +17 d&#233;g&#226;ts)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Pouvoirs magiques&lt;/b&gt;  (&lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; 17 ; &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;concentration&lt;/a&gt; +19)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
&#192; volont&#233; — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-Du-Mal.html&quot; title=&quot;D&#233;tection du Mal&quot;&gt;d&#233;tection du mal&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Sorts de paladin pr&#233;par&#233;s&lt;/b&gt;  (&lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; 14 ; &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;concentration&lt;/a&gt; +16)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
4e — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;p&#233;e-Sainte.html&quot; title=&quot;&#201;p&#233;e sainte&quot;&gt;&#233;p&#233;e sainte&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
3e — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arme-Magique-Supr&#234;me.html&quot; title=&quot;Arme magique supr&#234;me&quot;&gt;arme magique supr&#234;me&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pri&#232;re.html&quot; title=&quot;Pri&#232;re&quot;&gt;pri&#232;re&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
2e — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Protection-Dautrui.html&quot; title=&quot;Protection d&amp;#39;autrui&quot;&gt;protection d&#39;autrui&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ralentissement-Du-Poison.html&quot; title=&quot;Ralentissement du poison&quot;&gt;ralentissement du poison&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Splendeur-De-Laigle.html&quot; title=&quot;Splendeur de l&amp;#39;aigle&quot;&gt;splendeur de l&#39;aigle&lt;/a&gt;&lt;/i&gt; (2)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
1er — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;B&#233;n&#233;diction.html&quot; title=&quot;B&#233;n&#233;diction&quot;&gt;b&#233;n&#233;diction&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faveur-Divine.html&quot; title=&quot;Faveur divine&quot;&gt;faveur divine&lt;/a&gt;&lt;/i&gt; (2), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Protection-Contre-Le-Mal.html&quot; title=&quot;Protection contre le Mal&quot;&gt;protection contre le Mal&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Restauration-Partielle.html&quot; title=&quot;Restauration partielle&quot;&gt;restauration partielle&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Tactique&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Avant le combat.&lt;/b&gt; Le paladin lance &lt;i&gt;retardement du poison&lt;/i&gt; sur sa personne et &lt;i&gt;arme magique sup&#233;rieure&lt;/i&gt; sur son arme.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Pendant le combat.&lt;/b&gt; Si le paladin dispose de cibles rapproch&#233;es, il utilise Science de la frappe d&#233;cisive avec Encha&#238;nement.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Statistiques de base.&lt;/b&gt; Voici les statistiques du paladin sans &lt;i&gt;retardement du poison&lt;/i&gt; ni &lt;i&gt;arme magique sup&#233;rieure&lt;/i&gt; : &lt;b&gt;Immunit&#233;&lt;/b&gt; charme, coercition, maladie, terreur ; &lt;b&gt;Corps &#224; corps&lt;/b&gt; &lt;i&gt;hache d’armes naine de foudre +3&lt;/i&gt;, +25/+20/+15/+10 (1d10+7/19-20/x3 plus 1d6 &#233;lectricit&#233;)
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Statistiques&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 22, &lt;b&gt;Dex&lt;/b&gt; 8, &lt;b&gt;Con&lt;/b&gt; 16, &lt;b&gt;Int&lt;/b&gt; 10, &lt;b&gt;Sag&lt;/b&gt; 14, &lt;b&gt;Cha&lt;/b&gt; 14
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;BBA&lt;/b&gt; +17 ; &lt;b&gt;BMO&lt;/b&gt; +23 ; &lt;b&gt;DMD&lt;/b&gt; 34 (38 contre &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Bousculade.html&quot; title=&quot;bousculade&quot;&gt;bousculade&lt;/a&gt; ou en &lt;a class=&quot;pagelink&quot; href=&quot;Croc-En-Jambe.html&quot; title=&quot;croc-en-jambe&quot;&gt;croc-en-jambe&lt;/a&gt;)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Arme-De-Pr&#233;dilection.html&quot; title=&quot;Arme de pr&#233;dilection&quot;&gt;Arme de pr&#233;dilection&lt;/a&gt; (hache d&#39;armes naine), &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Puissance.html&quot; title=&quot;Attaque en puissance&quot;&gt;Attaque en puissance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Encha&#238;nement.html&quot; title=&quot;Encha&#238;nement&quot;&gt;Encha&#238;nement&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Frappe-D&#233;cisive.html&quot; title=&quot;Frappe d&#233;cisive&quot;&gt;Frappe d&#233;cisive&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Imposition-Des-Mains-Suppl&#233;mentaire.html&quot; title=&quot;Imposition des mains suppl&#233;mentaire&quot;&gt;Imposition des mains suppl&#233;mentaire&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Robustesse.html&quot; title=&quot;Robustesse&quot;&gt;Robustesse&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-La-Frappe-D&#233;cisive.html&quot; title=&quot;Science de la frappe d&#233;cisive&quot;&gt;Science de la frappe d&#233;cisive&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-Linitiative.html&quot; title=&quot;Science de l&amp;#39;initiative&quot;&gt;Science de l&#39;initiative&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Critique.html&quot; title=&quot;Science du critique&quot;&gt;Science du critique&lt;/a&gt; (hache d&#39;armes naine)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (folklore local) +2, &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (religion) +5, &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; +7, &lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt; +4, &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; +10, &lt;a class=&quot;pagelink&quot; href=&quot;Natation.html&quot; title=&quot;Natation&quot;&gt;Natation&lt;/a&gt; +4, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +12 (+14 pour remarquer les anomalies dans les structures de pierre), &lt;a class=&quot;pagelink&quot; href=&quot;Premiers-Secours.html&quot; title=&quot;Premiers secours&quot;&gt;Premiers secours&lt;/a&gt; +7
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Langues&lt;/b&gt; commun, nain
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Particularit&#233;s&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#AURADUBIEN&quot; title=&quot;Le paladin&quot;&gt;aura du Bien&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#CODEDECONDUITE&quot; title=&quot;Le paladin&quot;&gt;code de conduite&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#GRACES&quot; title=&quot;Le paladin&quot;&gt;gr&#226;ces&lt;/a&gt; (assourdi, h&#233;b&#233;t&#233;, naus&#233;eux, paralys&#233;, secou&#233;), &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#IMPOSTIONDESMAINS&quot; title=&quot;Le paladin&quot;&gt;impostion des mains&lt;/a&gt; (8d6, 12/day), &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#PACTEDIVIN&quot; title=&quot;Le paladin&quot;&gt;pacte divin&lt;/a&gt; (arme +5, 4/jour)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;&#201;quipement divers&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Crevice-(Armure).html&quot; title=&quot;Crevice&quot;&gt;crevice&lt;/a&gt; +3&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cu-(Armure).html&quot; title=&quot;&#201;cu (bois/acier)&quot;&gt;&#233;cu en acier&lt;/a&gt; +2&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Hache-Darmes-Naine-(Arme).html&quot; title=&quot;Hache d&amp;#39;armes naine&quot;&gt;hache d&#39;armes naine&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Foudre.html&quot; title=&quot;foudre (propri&#233;t&#233;)&quot;&gt;foudre&lt;/a&gt; +1&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Hache-De-Lancer-(Arme).html&quot; title=&quot;Hache de lancer&quot;&gt;hache de lancer&lt;/a&gt; +1&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-Darmure-Naturelle.html&quot; title=&quot;Amulette d&amp;#39;armure naturelle&quot;&gt;amulette d&#39;armure naturelle +1&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Anneau-De-Protection.html&quot; title=&quot;Anneau de protection&quot;&gt;anneau de protection +2&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-De-Belle-Allure.html&quot; title=&quot;Bandeau de belle allure&quot;&gt;bandeau de belle allure +2&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-De-Rapidit&#233;.html&quot; title=&quot;Bottes de rapidit&#233;&quot;&gt;bottes de rapidit&#233;&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-R&#233;sistance.html&quot; title=&quot;Cape de r&#233;sistance&quot;&gt;cape de r&#233;sistance +1&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinturon-De-Puissance-De-G&#233;ant.html&quot; title=&quot;Ceinturon de puissance de g&#233;ant&quot;&gt;ceinturon de puissance de g&#233;ant +4&lt;/a&gt;&lt;/i&gt;, anneaux de platine pour &lt;i&gt;protection d&#39;autrui&lt;/i&gt; (2, valant 50 po chacun), &lt;a class=&quot;pagelink&quot; href=&quot;Symbole-Sacr&#233;-(Objet).html&quot; title=&quot;Symbole sacr&#233;&quot;&gt;symbole sacr&#233; en argent&lt;/a&gt;, 1 667 po
&lt;/div&gt;
&lt;/div&gt;
&lt;/td&gt;&lt;td&gt;&lt;div&gt;Les seigneurs des haches prot&#232;gent les forteresses naines et chassent les ignobles monstres venus des entrailles du monde ainsi que les menaces &#233;trang&#232;res.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Edager Grisebarbe&lt;a class=&quot;headeranchor&quot; id=&quot;Edager_Grisebarbe_0&quot; href=&quot;#Edager_Grisebarbe_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Fier et sombre, Edager est un guerrier nain qui a beaucoup de mal &#224; faire confiance aux gens qui ne sont pas de sa race mais il r&#233;serve son hostilit&#233; aux gobelins, aux g&#233;ants, aux orques et aux autres cr&#233;atures mal&#233;fiques de l’Ombreterre.
&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
